PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, available INTEGER NOT NULL CHECK(available>=0), frozen INTEGER NOT NULL DEFAULT 0 CHECK(frozen>=0));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS exchanges(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),idem TEXT NOT NULL,coins INTEGER NOT NULL CHECK(coins>=100 AND coins<=1000000 AND coins%100=0),amount INTEGER NOT NULL CHECK(amount=coins/100),status TEXT NOT NULL CHECK(status IN ('PENDING','SUCCESS','FAILED')),mode TEXT NOT NULL,day TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,packet_id TEXT,expires INTEGER,recovered INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,error TEXT,UNIQUE(user_id,idem));
CREATE INDEX IF NOT EXISTS exchange_queue ON exchanges(status,next_attempt);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,exchange_id TEXT NOT NULL REFERENCES exchanges(id),kind TEXT NOT NULL CHECK(kind IN ('FREEZE','DEBIT','RELEASE')),coins INTEGER NOT NULL,created INTEGER NOT NULL,UNIQUE(exchange_id,kind));
CREATE TABLE IF NOT EXISTS user_settings(user_id TEXT PRIMARY KEY REFERENCES users(id),role TEXT NOT NULL DEFAULT 'USER' CHECK(role IN ('ADMIN','USER')),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL REFERENCES users(id),user_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota_resets(user_id TEXT NOT NULL REFERENCES users(id),day TEXT NOT NULL,last_order_rowid INTEGER NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user_id,day));
